-- Operational profile for public catalog entries: fees, caregiver ratio,
-- capacity, accepted ages, opening hours, packages and gallery.
--
-- The public datasets (039) do not contain these fields. Until a manager
-- claims a listing, the profile is SYNTHETIC (data_origin = 'synthetic',
-- generated by lib/daycare-synthetic.js) and every API response carries that
-- flag so the UI can label it as an estimate. Kept in a separate table so the
-- source data in daycare_listings is never mixed with generated values.
--
-- gallery_images holds app-relative paths of stock illustrations shipped in
-- /public/images (gallery_is_illustration = true). Real photos go to Storage
-- (daycare_listings.cover_image_path / gallery_paths) after manager approval.

BEGIN;

CREATE TABLE public.daycare_listing_profiles (
  listing_id uuid PRIMARY KEY REFERENCES public.daycare_listings(id) ON DELETE CASCADE,
  data_origin text NOT NULL DEFAULT 'synthetic'
    CHECK (data_origin IN ('synthetic', 'manager', 'verified')),
  generator_version text,
  description text NOT NULL CHECK (char_length(btrim(description)) BETWEEN 20 AND 1500),
  monthly_fee_min integer NOT NULL CHECK (monthly_fee_min > 0),
  monthly_fee_max integer NOT NULL,
  daily_fee integer NOT NULL CHECK (daily_fee > 0),
  registration_fee integer NOT NULL DEFAULT 0 CHECK (registration_fee >= 0),
  caregiver_ratio smallint NOT NULL CHECK (caregiver_ratio BETWEEN 1 AND 15),
  caregiver_count smallint NOT NULL CHECK (caregiver_count > 0),
  daily_capacity smallint NOT NULL CHECK (daily_capacity > 0),
  age_min_months smallint NOT NULL CHECK (age_min_months >= 0),
  age_max_months smallint NOT NULL,
  opening_time time NOT NULL,
  closing_time time NOT NULL,
  operating_days text NOT NULL CHECK (char_length(btrim(operating_days)) BETWEEN 3 AND 60),
  packages jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(packages) = 'array'),
  gallery_images text[] NOT NULL DEFAULT '{}'
    CHECK (array_to_string(gallery_images, ' ') ~ '^(/images/[a-z0-9-]+\.(webp|png|jpg)( |$))*$'),
  gallery_is_illustration boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (monthly_fee_max >= monthly_fee_min),
  CHECK (age_max_months > age_min_months),
  CHECK (closing_time > opening_time),
  CHECK (data_origin <> 'synthetic' OR generator_version IS NOT NULL)
);

CREATE INDEX daycare_listing_profiles_fee_idx ON public.daycare_listing_profiles (monthly_fee_min);
CREATE INDEX daycare_listing_profiles_ratio_idx ON public.daycare_listing_profiles (caregiver_ratio);

ALTER TABLE public.daycare_listing_profiles ENABLE ROW LEVEL SECURITY;

-- Same visibility as the listing itself (the subquery is subject to the
-- listing policies, so only published listings expose a profile).
CREATE POLICY daycare_listing_profiles_public_read
  ON public.daycare_listing_profiles
  FOR SELECT
  TO anon, authenticated
  USING (EXISTS (
    SELECT 1 FROM public.daycare_listings AS l
    WHERE l.id = daycare_listing_profiles.listing_id AND l.visibility = 'published'
  ));

CREATE POLICY daycare_listing_profiles_admin_read
  ON public.daycare_listing_profiles
  FOR SELECT
  TO authenticated
  USING (public.app_current_role() = 'admin');

-- Read-only through the Data API; the seed runs as postgres.
REVOKE ALL ON TABLE public.daycare_listing_profiles FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public.daycare_listing_profiles TO anon, authenticated;

COMMIT;
